import { readFile, writeFile } from 'node:fs/promises'
import openapiTS, { astToString } from 'openapi-typescript'

const source = new URL('../../api/openapi/openapi.json', import.meta.url)
const target = new URL('../app/shared/api/generated/', import.meta.url)
const banner =
  '// Generated by `pnpm api:generate` from apps/api/openapi/openapi.json. Do not edit.\n'

const document = JSON.parse(await readFile(source, 'utf8'))

const types = astToString(await openapiTS(document, { exportType: true }))
await writeFile(new URL('openapi.ts', target), banner + types)

const businessCode = document.components.schemas.BusinessCode
const names: string[] = businessCode['x-enum-varnames']
const codes: number[] = businessCode.enum
const entries = names.map((name, index) => `  ${name}: ${codes[index]},`).join('\n')
await writeFile(
  new URL('business-codes.ts', target),
  `${banner}export const BusinessCode = {\n${entries}\n} as const\n`,
)

type JsonSchema = {
  type?: string | string[]
  format?: string
  minLength?: number
  maxLength?: number
  minimum?: number
  maximum?: number
  pattern?: string
  enum?: unknown[]
  minItems?: number
  maxItems?: number
  items?: JsonSchema
  properties?: Record<string, JsonSchema>
  required?: string[]
  $ref?: string
  'x-max-text-length'?: number
}

type Operation = {
  requestBody?: { content?: Record<string, { schema?: { $ref?: string } }> }
}

const schemas: Record<string, JsonSchema> = document.components.schemas
const paths: Record<string, Record<string, Operation>> = document.paths
const bodies = new Set<string>()

function nameOf(reference: string): string {
  return reference.split('/').at(-1) ?? ''
}

function addWithParts(name: string): void {
  if (bodies.has(name)) {
    return
  }
  bodies.add(name)
  const pending = Object.values(schemas[name]?.properties ?? {})
  for (let field = pending.pop(); field !== undefined; field = pending.pop()) {
    if (field.$ref !== undefined) {
      addWithParts(nameOf(field.$ref))
    }
    pending.push(...Object.values(field.properties ?? {}), ...(field.items ? [field.items] : []))
  }
}

for (const operations of Object.values(paths)) {
  for (const operation of Object.values(operations)) {
    const reference = operation.requestBody?.content?.['application/json']?.schema?.$ref
    if (reference !== undefined) {
      addWithParts(nameOf(reference))
    }
  }
}

const constraintKeys = [
  'format',
  'minLength',
  'maxLength',
  'minimum',
  'maximum',
  'pattern',
  'enum',
  'minItems',
  'maxItems',
] as const

function fieldConstraint(field: JsonSchema, required: boolean) {
  const types = [field.type].flat().filter(type => type !== undefined)
  const constraint: Record<string, unknown> = {
    type: types.find(type => type !== 'null') ?? 'unknown',
    required,
    nullable: types.includes('null'),
  }
  for (const key of constraintKeys) {
    if (field[key] !== undefined) {
      constraint[key] = field[key]
    }
  }
  if (field.items?.enum !== undefined) {
    constraint.itemEnum = field.items.enum
  }
  if (field['x-max-text-length'] !== undefined) {
    constraint.maxTextLength = field['x-max-text-length']
  }
  if (field.properties !== undefined) {
    constraint.fields = fieldConstraints(field)
  }
  return constraint
}

function fieldConstraints(schema: JsonSchema): Record<string, unknown> {
  const required = new Set(schema.required ?? [])
  const fields = Object.entries(schema.properties ?? {})
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, field]) => [name, fieldConstraint(field, required.has(name))])
  return Object.fromEntries(fields)
}

const constraints = Object.fromEntries(
  [...bodies].sort().map(body => [body, fieldConstraints(schemas[body] ?? {})]),
)

await writeFile(
  new URL('constraints.ts', target),
  `${banner}export const constraints = ${JSON.stringify(constraints, null, 2)} as const\n`,
)
